sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   //Type appropriate comment here, and begin script below
   let [day, month, year] = newValue.split("/");
   let formDate = new Date(year, month-1, day), currentDate = new Date();
//    g_form.addErrorMessage(formDate);
//    g_form.addErrorMessage(currentDate);

   if(currentDate > formDate){
	g_form.addErrorMessage("Invalid date! You must select a future date.");
	g_form.setValue("trainning_date", "");
   }
   else {
	g_form.clearMessages();
   }
}
